{"node_id": "LVMC_11_38_030", "law_refs": ["LVMC-11-38-030"], "subject": {"binder": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-135::motorcycle", "ru.moped", "ru.electric_scooter"]}, "segmentation": [{"id": "s1", "text": "No motorcycle or motor scooter", "role": "subject"}, {"id": "s2", "text": "shall be ridden upon any sidewalk", "role": "obligation"}, {"id": "s3", "text": "of the City", "role": "condition"}], "elements": [{"span": "s1", "atoms": ["ru.aggregate=DEF-NRS-484A-135::motorcycle", "ru.moped", "ru.electric_scooter"], "derived": [], "justification": "'motorcycle' is the admitted aggregate DEF-NRS-484A-135::motorcycle ('every motor vehicle equipped with a seat or saddle for the use of the driver and designed to travel on not more than three wheels in contact with the ground, excluding an electric bicycle, a tractor or a moped'), claimed as one atom and never expanded. 'motor scooter' has no applicable definition and the table admits no aggregate for it, so its ordinary words, a scooter propelled by a motor, are carried by the class atoms whose contracts denote such machines: ru.moped ('a low-power two- or three-wheeler with a small engine or motor', the class whose corpus definition names a 'motor-driven scooter') and ru.electric_scooter ('a standing or seated electric scooter with handlebars'); a motor scooter above the moped class is a motor vehicle on not more than three wheels with a seat, so already a member of the motorcycle aggregate. ru.pedestrian is not read: its contract is 'Not a stand-in for: a person on a bicycle or scooter'. 'No' states the prohibition the obligation span carries."}, {"span": "s2", "atoms": ["st.sidewalk", "rel.occupies"], "derived": ["drv.motion.moving"], "justification": "st.sidewalk is the 'area for pedestrians between roadway and property line', the extent of DEF-NRS-484A-240 ('that portion of a highway between the curb lines or the lateral lines of a highway and the adjacent property lines intended for the use of pedestrians'); its exclusion 'Not a stand-in for: a crosswalk' is kept: a crosswalk is not read as a sidewalk. rel.occupies ('a road user's footprint overlaps a lane / region') anchors 'upon' to the subject's own sidewalk, and 'any' makes every sidewalk region count. 'be ridden' is the machine's controlled motion, drv.motion.moving (speed above the source's resolution), under the agency reading disclosed below."}], "operationalizations": [], "assumptions": [{"span": "s3", "id": "asm.within_city_limits", "meaning": "The place of the observation lies inside the territorial limits of an incorporated city, as declared for the map or the trace."}], "intentions": [], "compositions": [], "residues": [], "binders": [{"name": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-135::motorcycle", "ru.moped", "ru.electric_scooter"]}], "applicability": "x is a motorcycle (ru.aggregate DEF-NRS-484A-135::motorcycle), a moped (ru.moped) or an electric scooter (ru.electric_scooter), and asm.within_city_limits holds at the observation.", "obligation": "At the observation, x is not both moving (drv.motion.moving(x) with speed_floor p.speed_resolution) and occupying (rel.occupies) any st.sidewalk region.", "params": ["p.speed_resolution"], "narrowings": [{"span": "s2", "why": "'be ridden' is read through the machine's controlled motion: a motorcycle or scooter moving above the speed resolution while its footprint overlaps a sidewalk is taken to be ridden there, one standing still is not; who or what is at the controls is not observed.", "kind": "observable_reading", "category": "agency"}], "scenarios": [{"name": "forbid", "expected": "violated", "narrative": "Inside declared city limits, a motorcycle travels along a sidewalk at walking pace; its footprint overlaps the sidewalk region and its speed is well above the resolution."}, {"name": "permit", "expected": "compliant", "narrative": "Inside declared city limits, a motorcycle travels in a lane of the roadway, overlapping no sidewalk."}, {"name": "idle", "expected": "not_applicable", "narrative": "A bicycle is ridden along a sidewalk inside declared city limits; it is neither in the motorcycle aggregate nor a moped nor an electric scooter."}, {"name": "blind", "expected": "unknown", "narrative": "Inside declared city limits, a moped moves near the curb; the source declares rel.occupies absent, so whether it is on the sidewalk is not observed.", "masked": ["rel.occupies"]}, {"name": "branch_1", "expected": "compliant", "narrative": "Inside declared city limits, a motorcycle stands parked on a sidewalk with zero speed: it is not ridden there."}], "literals": [], "param_proposals": [{"name": "p.speed_resolution", "unit": "m/s", "value": 0.2, "convention": "Sensor resolution: the smallest speed the acquisition standard separates from standstill; a speed at or below it counts as no motion.", "source": "Ground-truth simulator kinematics sampled at 20 Hz and the speed noise of typical odometry"}], "gaps": []}
{"node_id": "LVMC_11_43_010_A", "law_refs": ["LVMC-11-43-010-A"], "subject": {"binder": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}, "segmentation": [{"id": "t1", "text": "The following regulations pertain to the operation of", "role": "boilerplate"}, {"id": "t2", "text": "vehicles", "role": "subject"}, {"id": "t3", "text": "within a roundabout", "role": "condition"}, {"id": "t4", "text": "All vehicular travel shall be in a counterclockwise direction", "role": "obligation"}], "elements": [{"span": "t2", "atoms": ["ru.aggregate=DEF-NRS-484A-320::vehicle"], "derived": [], "justification": "'vehicles' is the admitted aggregate DEF-NRS-484A-320::vehicle ('every device in, upon or by which any person or property is or may be transported or drawn upon a highway', with its exceptions), claimed as one atom."}, {"span": "t3", "atoms": ["st.roundabout", "rel.occupies"], "derived": [], "justification": "st.roundabout is 'a rotary intersection: its central island, its circulatory roadway and its entry and exit approaches', which denotes DEF-LVMC-11-02-130 ('an intersection characterized by a circulatory roadway, channelized approaches and yield control of entering traffic', encompassing 'the area bounded by the outermost curb line' and including 'the crosswalks on any entering or exiting roadway': the entry and exit approaches the contract names). rel.occupies ('a road user's footprint overlaps a lane / region') anchors 'within' to the roundabout the vehicle is in."}, {"span": "t4", "atoms": ["ru.aggregate=DEF-NRS-484A-320::vehicle", "st.roundabout", "st.region_geometry", "kin.position", "kin.velocity", "kin.speed"], "derived": ["drv.motion.clockwise_about_region"], "justification": "'vehicular travel' is the motion of the vehicle the subject span binds (the same aggregate). 'in a counterclockwise direction' is the sense of that motion about the roundabout: drv.motion.clockwise_about_region reads the vector from the region's reference point (st.region_geometry, 'the reference point and the boundary polygon of a structure region in the world frame') to the vehicle's position (kin.position) against its velocity (kin.velocity, 'velocity vector', world frame) and speed (kin.speed); its own exclusion makes it no stand-in for travel against a lane direction, so no lane marking or st.lane_direction is read. The duty is violated by clockwise motion; motion toward or away from the centre (entering, leaving) and standstill are neither sense and do not violate it."}], "operationalizations": [], "assumptions": [], "intentions": [], "compositions": [], "residues": [], "binders": [{"name": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}], "applicability": "x is a vehicle (ru.aggregate DEF-NRS-484A-320::vehicle) and occupies (rel.occupies) some st.roundabout region at the observation.", "obligation": "For every st.roundabout region r that x occupies at the observation, x is not moving clockwise about r: not drv.motion.clockwise_about_region(x, r) with speed_floor p.speed_resolution and sine_tolerance p.circulation_sine_tolerance.", "params": ["p.speed_resolution", "p.circulation_sine_tolerance"], "narrowings": [{"span": "t4", "why": "'counterclockwise' is read as the sense of the vehicle's motion about the roundabout region's reference point (st.region_geometry), taken as the centre its circulatory roadway runs around, viewed from above; the duty is judged by the absence of the opposite (clockwise) sense, so a vehicle at rest or moving radially within the tolerance (entering or leaving) complies.", "kind": "reading"}], "scenarios": [{"name": "forbid", "expected": "violated", "narrative": "A car on the circulatory roadway of a roundabout drives around the central island clockwise, its velocity tangential to the island."}, {"name": "permit", "expected": "compliant", "narrative": "A car on the circulatory roadway drives around the central island counter-clockwise."}, {"name": "idle", "expected": "not_applicable", "narrative": "A car drives clockwise around a block on ordinary streets; it occupies no roundabout region."}, {"name": "blind", "expected": "unknown", "narrative": "A car is on the circulatory roadway of a roundabout and moving; the source declares kin.velocity absent, so the sense of its motion is not observed.", "masked": ["kin.velocity"]}, {"name": "branch_1", "expected": "compliant", "narrative": "A car on an entry approach inside the roundabout's outline drives straight toward the central island before yielding: its motion is radial, neither sense."}], "literals": [], "param_proposals": [{"name": "p.speed_resolution", "unit": "m/s", "value": 0.2, "convention": "Sensor resolution: the smallest speed the acquisition standard separates from standstill; a speed at or below it counts as no motion.", "source": "Ground-truth simulator kinematics sampled at 20 Hz and the speed noise of typical odometry"}, {"name": "p.circulation_sine_tolerance", "unit": "1", "value": 0.2, "convention": "Direction tolerance: the sine of the largest angle off a radial line within which motion about a point counts as neither sense of rotation, covering heading and position noise on entry and exit paths.", "source": "Measurement tolerance of velocity direction in ground-truth simulation"}], "gaps": []}
{"node_id": "NRS_484B_113_2", "law_refs": ["NRS-484B-113-2"], "subject": {"binder": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}, "segmentation": [{"id": "b1", "text": "The driver of a vehicle", "role": "subject"}, {"id": "b2", "text": "Shall not back into an intersection", "role": "obligation"}, {"id": "b3", "text": "on or over a crosswalk", "role": "obligation"}, {"id": "b4", "text": "or around a", "role": "obligation"}, {"id": "b5", "text": "street", "role": "condition"}, {"id": "b6", "text": "corner", "role": "obligation"}], "elements": [{"span": "b1", "atoms": ["ru.aggregate=DEF-NRS-484A-320::vehicle"], "derived": [], "justification": "'vehicle' is the admitted aggregate DEF-NRS-484A-320::vehicle, claimed as one atom. 'driver' is no aggregate: DEF-NRS-484A-080 'every person who drives or is in actual physical control of a vehicle' names a relational role, read through the vehicle's controlled motion (agency reading below), so the duty binds the vehicle's conduct."}, {"span": "b2", "atoms": ["st.intersection", "rel.occupies"], "derived": ["drv.motion.reversing"], "justification": "st.intersection is 'the region where two roadways meet, bounded by the prolongation of their edges; a junction where an alley meets another way ... is no intersection', which denotes DEF-NRS-484A-105 (1) 'the area embraced within the prolongation or connection of the lateral curb lines' and (3) 'The junction of an alley with a street, road or highway shall not constitute an intersection'; its exclusion 'Not a stand-in for: a crosswalk or a stop line' is kept: entry into the intersection region itself is read. 'back' is drv.motion.reversing (velocity along heading below minus the resolution, never kin.gear, which is 'Not a stand-in for: the direction of motion'). 'into' is the observation at which x's footprint begins to overlap the intersection (rel.occupies rising) while reversing."}, {"span": "b3", "atoms": ["st.crosswalk", "rel.occupies"], "derived": ["drv.motion.reversing"], "justification": "st.crosswalk is the 'marked crossing, or the unmarked prolongation of sidewalks at an intersection', which denotes both limbs of DEF-NRS-484A-065 ('That part of a highway at an intersection included within the connections of the lateral lines of the sidewalks' and 'Any portion of a highway at an intersection or elsewhere distinctly indicated for pedestrian crossing'). 'on or over' is x's footprint overlapping the crosswalk (rel.occupies) at an observation at which x is reversing (drv.motion.reversing): on it, or passing over it."}, {"span": "b4", "atoms": ["kin.velocity", "kin.heading", "kin.yaw_rate"], "derived": ["drv.motion.reversing", "drv.motion.yawing"], "justification": "'around' a corner, said of backing, is reversing (drv.motion.reversing, from kin.velocity and kin.heading) while the heading changes (drv.motion.yawing, the absolute kin.yaw_rate above the resolution: 'rate of change of heading'); kin.yaw_rate's exclusion 'Not a stand-in for: road curvature' is respected: the vehicle's own heading change is read, not the road's shape."}, {"span": "b6", "atoms": ["st.intersection", "rel.occupies"], "derived": [], "justification": "A street corner is the corner where ways meet: read as the st.intersection region ('the region where two roadways meet, bounded by the prolongation of their edges'), whose corners are where the curb lines prolonged by DEF-NRS-484A-105 meet; rel.occupies anchors the backing vehicle to it. The highway part of DEF-NRS-484A-265 ('the entire width between the boundary lines of every highway ... open to the use of the public for purposes of vehicular traffic') is the ways the intersection lies on; its city part is carried by the assumption on 'street'."}], "operationalizations": [], "assumptions": [{"span": "b5", "id": "asm.within_city_limits", "meaning": "The place of the observation lies inside the territorial limits of an incorporated city, as declared for the map or the trace."}], "intentions": [], "compositions": [], "residues": [], "binders": [{"name": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}], "applicability": "x is a vehicle (ru.aggregate DEF-NRS-484A-320::vehicle).", "obligation": "At the observation none of the following holds: (a) x is reversing (drv.motion.reversing(x), speed_floor p.speed_resolution) and its footprint begins here to overlap (rel.occupies rising) some st.intersection region; (b) x is reversing and occupies (rel.occupies) some st.crosswalk region; (c) asm.within_city_limits holds, x is reversing and yawing (drv.motion.yawing(x), yaw_floor p.yaw_rate_resolution), and x occupies some st.intersection region.", "params": ["p.speed_resolution", "p.yaw_rate_resolution"], "narrowings": [{"span": "b1", "why": "'The driver of a vehicle' is read through the vehicle's controlled motion: a vehicle moving on the road is taken to be driven, and the duty binds that vehicle's conduct whoever or whatever controls it.", "kind": "observable_reading", "category": "agency"}, {"span": "b6", "why": "The street corner is read as the intersection region whose corner the vehicle backs around: backing around it is reversing with the heading changing while the footprint overlaps an intersection; the curb corner outside the intersection outline is not a mapped region and is not read.", "kind": "reading"}], "scenarios": [{"name": "forbid", "expected": "violated", "narrative": "A car reverses along a street and its rear footprint begins to overlap the intersection region at the end of the block."}, {"name": "permit", "expected": "compliant", "narrative": "A car reverses into a parking bay mid-block, overlapping no intersection and no crosswalk."}, {"name": "idle", "expected": "not_applicable", "narrative": "A bicycle, a device moved by human power and so no vehicle, is walked backwards across a crosswalk."}, {"name": "blind", "expected": "unknown", "narrative": "A car's footprint overlaps a crosswalk; the source declares kin.velocity absent, so whether it is reversing is not observed.", "masked": ["kin.velocity"]}, {"name": "branch_1", "expected": "violated", "narrative": "A car stopped past the stop line reverses so that its footprint overlaps the marked crosswalk behind it."}, {"name": "branch_2", "expected": "violated", "narrative": "Inside declared city limits, a car already within an intersection reverses while its heading swings to the side, backing around the corner into the cross street."}, {"name": "branch_3", "expected": "compliant", "narrative": "Outside declared city limits, a car already within an intersection and clear of every crosswalk reverses while its heading swings: no street corner is involved and no entry into the intersection occurs."}], "literals": [], "param_proposals": [{"name": "p.speed_resolution", "unit": "m/s", "value": 0.2, "convention": "Sensor resolution: the smallest speed the acquisition standard separates from standstill; a speed at or below it counts as no motion.", "source": "Ground-truth simulator kinematics sampled at 20 Hz and the speed noise of typical odometry"}, {"name": "p.yaw_rate_resolution", "unit": "deg/s", "value": 2.0, "convention": "Sensor resolution: the smallest yaw rate the acquisition standard separates from a straight path; a yaw rate at or below it counts as no heading change.", "source": "Yaw-rate noise of ground-truth simulator kinematics and of automotive inertial sensors"}], "gaps": []}
{"node_id": "NRS_484B_127_3", "law_refs": ["NRS-484B-127-3"], "subject": {"binder": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-130::motor_vehicle"]}, "segmentation": [{"id": "c1", "text": "Motor vehicles being driven", "role": "subject"}, {"id": "c2", "text": "upon any highway", "role": "trigger"}, {"id": "c3", "text": "outside of a business district", "role": "condition"}, {"id": "c4", "text": "in a caravan or motorcade", "role": "condition"}, {"id": "c5", "text": "whether or not towing other vehicles", "role": "condition"}, {"id": "c6", "text": "shall be operated to allow", "role": "obligation"}, {"id": "c7", "text": "sufficient space between each such vehicle or combination of vehicles so as to enable any other vehicle or combination of vehicles to enter and occupy such space without danger", "role": "standard"}], "elements": [{"span": "c1", "atoms": ["ru.aggregate=DEF-NRS-484A-130::motor_vehicle"], "derived": [], "justification": "'Motor vehicles' is the admitted aggregate DEF-NRS-484A-130::motor_vehicle ('every vehicle which is self-propelled but not operated upon rails'), claimed as one atom. 'being driven' is read through the vehicle's controlled motion (agency reading below)."}, {"span": "c2", "atoms": ["st.highway", "rel.occupies"], "derived": [], "justification": "st.highway is 'the entire public way between its boundary lines', which denotes DEF-NRS-484A-095 ('the entire width between the boundary lines of every way dedicated to a public authority when any part of the way is open to the use of the public for purposes of vehicular traffic'); its exclusion 'Not a stand-in for: the roadway' is respected: the whole way is read. rel.occupies anchors 'upon' to the highway the vehicle is on."}, {"span": "c4", "atoms": ["rel.ahead_behind_in_lane", "rel.same_direction", "ru.aggregate=DEF-NRS-484A-130::motor_vehicle"], "derived": [], "justification": "Nearest atoms only (gap below): membership of a caravan or motorcade, an organized group of vehicles proceeding together, has no atom. rel.ahead_behind_in_lane ('a is ahead of / behind b in the same lane') and rel.same_direction ('headings aligned') relate the subject to the motor vehicle ahead of it, but they hold for any two vehicles following each other in a lane, members of a group or not, so they do not tell a caravan from ordinary traffic."}, {"span": "c6", "atoms": ["rel.surface_gap", "rel.ahead_behind_in_lane"], "derived": [], "justification": "'shall be operated to allow' a space is the vehicle's conduct of keeping a gap to the caravan vehicle ahead of it in its lane: rel.surface_gap ('distance between the nearest points of two bodies'; its longitudinal component along the subject's heading) to the road user rel.ahead_behind_in_lane places ahead. 'operated' is read through the vehicle's controlled motion (agency reading below)."}], "operationalizations": [{"span": "c7", "standard": "sufficient space between each such vehicle or combination of vehicles so as to enable any other vehicle or combination of vehicles to enter and occupy such space without danger", "concepts": ["rel.surface_gap", "rel.ahead_behind_in_lane", "rel.same_direction", "kin.speed", "ru.aggregate=DEF-NRS-484A-320::vehicle", "ru.aggregate=DEF-NRS-484A-050::combination_of_vehicles"], "params": ["p.entering_combination_length", "p.entry_time_headway", "p.same_direction_cosine"], "convention": "Gap acceptance for a vehicle merging into a column: the space between consecutive caravan vehicles must hold the longest combination of vehicles that may enter (a design-vehicle length) plus a time headway at the subject's current speed to the caravan vehicle ahead of the entering one and the same headway from the subject behind it; the bound rises with the subject's speed (kin.speed). 'each such vehicle or combination of vehicles' is the caravan vehicle ahead of the subject, a vehicle (DEF-NRS-484A-320::vehicle) or a combination (DEF-NRS-484A-050::combination_of_vehicles, 'two or more vehicles coupled together'), in the subject's lane (rel.ahead_behind_in_lane) and direction (rel.same_direction).", "surrogate": false}], "assumptions": [{"span": "c3", "id": "asm.outside_business_district", "meaning": "The place of the observation lies outside every business district declared for the map or the trace."}], "intentions": [], "compositions": [], "residues": [{"span": "c5", "why": "The duty is the same for a caravan vehicle that tows another vehicle and for one that does not: the words say so ('whether or not'); a towing vehicle and what it tows form a combination of vehicles, whose gap to the vehicle ahead is read from the combination's body through the aggregate the standard names.", "scope": "none"}], "binders": [{"name": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-130::motor_vehicle"]}], "applicability": "x is a motor vehicle (ru.aggregate DEF-NRS-484A-130::motor_vehicle) occupying (rel.occupies) a st.highway region, asm.outside_business_district holds, and x travels in a caravan or motorcade (gap ru.procession_member; nearest reading: some other motor vehicle of the same group travels in x's lane ahead of x (rel.ahead_behind_in_lane) and in x's direction (rel.same_direction, tolerance p.same_direction_cosine)).", "obligation": "For every road user y other than x that is a vehicle (ru.aggregate DEF-NRS-484A-320::vehicle) or a combination of vehicles (ru.aggregate DEF-NRS-484A-050::combination_of_vehicles), belongs to x's caravan, is ahead of x in its lane (rel.ahead_behind_in_lane) and travels in x's direction (rel.same_direction, p.same_direction_cosine): the longitudinal component of rel.surface_gap between x and y is at least p.entering_combination_length plus p.entry_time_headway times x's speed (kin.speed) for the gap ahead of the entering vehicle plus p.entry_time_headway times x's speed for the gap behind it.", "params": ["p.entering_combination_length", "p.entry_time_headway", "p.same_direction_cosine"], "narrowings": [{"span": "c1", "why": "'being driven' is read through the vehicle's controlled motion: a motor vehicle moving on the highway is taken to be driven, whoever or whatever controls it.", "kind": "observable_reading", "category": "agency"}, {"span": "c6", "why": "'operated' is read through the vehicle's controlled motion: the gap the vehicle keeps is its conduct, whoever or whatever controls it.", "kind": "observable_reading", "category": "agency"}, {"span": "c7", "why": "'without danger' is read only through the length of the longest combination that may enter and a time headway at the subject's speed on each side of it; other factors of danger (weather, grade, sight distance, the entering vehicle's speed) are not read, and 'any other vehicle or combination of vehicles' is read through that one design length.", "kind": "reading"}], "scenarios": [{"name": "forbid", "expected": "violated", "narrative": "On a rural highway declared outside every business district, three cars travel as a funeral motorcade in one lane at highway speed; the second car keeps a longitudinal gap to the first shorter than the length of an entering tractor-trailer combination."}, {"name": "permit", "expected": "compliant", "narrative": "The same motorcade, each follower keeping a gap to the car ahead longer than an entering combination plus a time headway at its speed on each side."}, {"name": "idle", "expected": "not_applicable", "narrative": "The same tightly spaced motorcade travels through a place declared a business district."}, {"name": "blind", "expected": "unknown", "narrative": "The rural motorcade as in forbid; the source declares rel.surface_gap absent, so the gap the follower keeps is not observed.", "masked": ["rel.surface_gap"]}, {"name": "branch_1", "expected": "compliant", "narrative": "The lead car of a rural motorcade has no vehicle of any kind ahead of it in the scene: there is no space for it to keep, and it binds alone."}], "literals": [], "param_proposals": [{"name": "p.entering_combination_length", "unit": "m", "value": 22.4, "convention": "Design-vehicle length: the overall length of the longest combination of vehicles a highway is designed to carry, standing for 'any other vehicle or combination of vehicles' that may enter the space.", "source": "AASHTO Green Book design vehicles (WB-67 interstate semitrailer, 73.5 ft)"}, {"name": "p.entry_time_headway", "unit": "s", "value": 2.0, "convention": "Safe time headway: the time gap kept to the vehicle ahead, applied once ahead of and once behind the entering vehicle at the subject's speed.", "source": "Two-second following rule of driver manuals and headway-based car-following conventions"}, {"name": "p.same_direction_cosine", "unit": "1", "value": 0.9, "convention": "Heading alignment tolerance: the cosine of the largest angle between two headings that still counts as travelling the same way.", "source": "Measurement tolerance of heading in ground-truth simulation and lane-keeping heading variation"}], "gaps": [{"span": "c4", "kind": "atom", "proposal": "`ru.procession_member` | a road user travelling as a member of an organized group of vehicles proceeding together in a column (a caravan, motorcade, convoy or procession), as the source labels the group; **group** attribute identifying the group, so that two road users are members of the same one **Not a stand-in for:** vehicles that merely follow one another in the same lane | general", "nearest": ["rel.ahead_behind_in_lane", "rel.same_direction"]}]}
{"node_id": "NRS_484B_210_3", "law_refs": ["NRS-484B-210-3"], "subject": {"binder": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}, "segmentation": [{"id": "f1", "text": "The driver of a vehicle", "role": "subject"}, {"id": "f2", "text": "shall not overtake and pass another vehicle upon the right", "role": "obligation"}, {"id": "f3", "text": "when such movement requires driving off the paved portion of the highway", "role": "condition"}], "elements": [{"span": "f1", "atoms": ["ru.aggregate=DEF-NRS-484A-320::vehicle"], "derived": [], "justification": "'vehicle' is the admitted aggregate DEF-NRS-484A-320::vehicle, claimed as one atom. 'driver' (DEF-NRS-484A-080, 'every person who drives or is in actual physical control of a vehicle') is a relational role read through the vehicle's controlled motion (agency reading below)."}, {"span": "f2", "atoms": ["ru.aggregate=DEF-NRS-484A-320::vehicle", "rel.same_direction", "rel.longitudinal_overlap", "rel.bearing", "kin.speed"], "derived": ["drv.interaction.passing_on_right"], "justification": "'another vehicle' is a road user of the admitted aggregate DEF-NRS-484A-320::vehicle other than the subject, quantified because it is present only sometimes. 'overtake and pass ... upon the right' is drv.interaction.passing_on_right(x, y): headings aligned (rel.same_direction), bodies side by side along x's heading (rel.longitudinal_overlap, 'the bodies overlap along the subject's heading (side by side)'), y on x's left (rel.bearing, 'for \"on the right of\"'), x faster than y (kin.speed). rel.longitudinal_overlap is 'neither a contact nor a distance between the bodies' and is read only as side-by-side."}, {"span": "f3", "atoms": ["st.shoulder", "st.road_edge", "rel.occupies"], "derived": [], "justification": "The paved portion of the highway (DEF-NRS-484A-095, 'the entire width between the boundary lines of every way') is told from the unpaved by the paved attributes the ontology carries: st.shoulder 'the part of the highway beside the roadway not intended for vehicular traffic; paved attribute' and st.road_edge 'curb or edge of the roadway; paved attribute for the surface beyond it'. 'driving off the paved portion' is x's footprint overlapping (rel.occupies) a shoulder whose paved attribute is false, or a road edge whose surface beyond is unpaved. 'such movement requires' is read by the movement as made: the pass that is made with the vehicle off the pavement at the same observation is the one the words name."}], "operationalizations": [], "assumptions": [], "intentions": [], "compositions": [], "residues": [], "binders": [{"name": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}], "applicability": "x is a vehicle (ru.aggregate DEF-NRS-484A-320::vehicle) and, at the observation, x is off the paved portion of the highway: it occupies (rel.occupies) a st.shoulder region whose paved attribute is false, or a st.road_edge whose paved attribute (the surface beyond it) is false.", "obligation": "At the observation there is no road user y other than x that is a vehicle (ru.aggregate DEF-NRS-484A-320::vehicle) and that x is passing on y's right: not drv.interaction.passing_on_right(x, y) with aligned_cosine p.same_direction_cosine and speed_margin p.overtaking_speed_margin.", "params": ["p.same_direction_cosine", "p.overtaking_speed_margin"], "narrowings": [{"span": "f1", "why": "'The driver of a vehicle' is read through the vehicle's controlled motion: a vehicle moving on the road is taken to be driven, and the duty binds that vehicle's conduct whoever or whatever controls it.", "kind": "observable_reading", "category": "agency"}, {"span": "f2", "why": "'overtake and pass' is judged at the side-by-side phase of the movement (drv.interaction.passing_on_right): an approach from behind on the unpaved surface that never comes alongside, and the return ahead of the other vehicle after the bodies no longer overlap, are not judged by this node.", "kind": "reading"}, {"span": "f3", "why": "'driving' off the pavement is read through the vehicle's controlled motion over the unpaved surface, whoever or whatever controls it.", "kind": "observable_reading", "category": "agency"}], "scenarios": [{"name": "forbid", "expected": "violated", "narrative": "On a two-lane highway a car moves onto the unpaved shoulder and drives alongside a slower car that waits to turn left, the slower car on its left, the bodies side by side."}, {"name": "permit", "expected": "compliant", "narrative": "A car alone in the scene pulls onto the unpaved shoulder and slows to a stop: it passes no vehicle, and the duty binds it alone."}, {"name": "idle", "expected": "not_applicable", "narrative": "On a highway with two lanes in its direction, a car passes a slower car on its right within the paved right lane, never leaving the pavement."}, {"name": "blind", "expected": "unknown", "narrative": "A car on the unpaved shoulder moves faster than a car beside it; the source declares rel.bearing absent, so on which side of it the other car lies is not observed.", "masked": ["rel.bearing"]}, {"name": "branch_1", "expected": "compliant", "narrative": "A car crawling on the unpaved shoulder is overtaken by a faster car in the lane on its left: the subject is slower and passes no one."}], "literals": [], "param_proposals": [{"name": "p.same_direction_cosine", "unit": "1", "value": 0.9, "convention": "Heading alignment tolerance: the cosine of the largest angle between two headings that still counts as travelling the same way.", "source": "Measurement tolerance of heading in ground-truth simulation and lane-keeping heading variation"}, {"name": "p.overtaking_speed_margin", "unit": "m/s", "value": 0.5, "convention": "Speed resolution of a speed difference: the smallest excess of the subject's speed over the other's that counts as gaining on it rather than keeping pace.", "source": "Speed noise of ground-truth simulator kinematics, doubled for a difference of two readings"}], "gaps": []}
{"node_id": "NRS_484B_223_4a", "law_refs": ["NRS-484B-223-4a"], "subject": {"binder": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}, "segmentation": [{"id": "d1", "text": "If a highway has been designed to provide", "role": "condition"}, {"id": "d2", "text": "a single right lane to be used only for turning", "role": "condition"}, {"id": "d3", "text": "a vehicle must", "role": "subject"}, {"id": "d4", "text": "Be driven in the right turn lane", "role": "obligation"}, {"id": "d5", "text": "only for the purpose of making a right turn", "role": "obligation"}], "elements": [{"span": "d1", "atoms": ["st.highway", "st.on_way"], "derived": [], "justification": "st.highway is 'the entire public way between its boundary lines', denoting DEF-NRS-484A-095 ('the entire width between the boundary lines of every way dedicated to a public authority ...'); st.on_way ('the public way (a highway region) a structure region lies on — a lane, roadway, ...') ties the turn lane to that highway. 'has been designed to provide' is the lane's presence on the map (status reading below)."}, {"span": "d2", "atoms": ["st.turn_lane", "st.lane", "st.lane_adjacency"], "derived": [], "justification": "st.turn_lane is 'a lane designated only for turning; side ∈ {left, right}', with side right: 'a ... right lane to be used only for turning'. 'single' is read as no neighbouring lane being a right turn lane too: st.lane_adjacency gives the 'left / right neighbouring lane of the same direction' (its exclusion 'Not a stand-in for: the marking between two lanes' is respected: lanes, not markings, are compared), so a pair of adjacent right turn lanes is not a single one."}, {"span": "d3", "atoms": ["ru.aggregate=DEF-NRS-484A-320::vehicle"], "derived": [], "justification": "'a vehicle' is the admitted aggregate DEF-NRS-484A-320::vehicle, claimed as one atom; 'must' introduces the duty the obligation spans state."}, {"span": "d4", "atoms": ["st.turn_lane", "st.lane", "st.lane_adjacency", "st.intersection", "rel.occupies"], "derived": [], "justification": "'the right turn lane' is the lane L the condition singles out (st.turn_lane, side right); 'driven in' it is x's footprint overlapping it (rel.occupies). Driving in it other than for the turn shows where x leaves it into the neighbouring lane on its left (st.lane_adjacency, 'left / right neighbouring lane of the same direction') short of the intersection it enters (st.intersection), instead of turning."}, {"span": "d5", "atoms": ["st.intersection", "st.lane_enters", "rel.occupies", "kin.yaw_rate"], "derived": ["drv.motion.heading_change_since_entry"], "justification": "The right turn the lane serves is made at the intersection L runs into: st.lane_enters ('the intersection region a directed approach carrier runs into at its entrance end'), an st.intersection ('the region where two roadways meet', DEF-NRS-484A-105). 'making a right turn' is read by the heading change of x since its footprint began to overlap that intersection (drv.motion.heading_change_since_entry, integrated from kin.yaw_rate, left positive) reaching minus the turn recognition angle by the time x leaves it; kin.yaw_rate is 'Not a stand-in for: road curvature', and the quantity is compared at the exit, after the whole passage. 'the purpose of' is read through the conduct it explains (reading below)."}], "operationalizations": [], "assumptions": [], "intentions": [], "compositions": [], "residues": [], "binders": [{"name": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}], "applicability": "x is a vehicle (ru.aggregate DEF-NRS-484A-320::vehicle) and x occupies (rel.occupies) at the observation, or occupied at an earlier observation, a single right turn lane L: an st.turn_lane region of side right lying on (st.on_way) an st.highway region, with no lane adjacent to it (st.lane_adjacency) that is also an st.turn_lane of side right.", "obligation": "Re-binding L with the same selection and I as the st.intersection region L enters (st.lane_enters): at the observation neither (a) x stops here occupying L (rel.occupies of x and L false here and true at the previous observation) while occupying the lane adjacent to L on its left (st.lane_adjacency) and not occupying I; nor (b) x stops here occupying I, having begun to overlap I at an observation at which it occupied L, and its heading change since that entry (drv.motion.heading_change_since_entry(x, I), step p.heading_since_step_carla_scene_graph) is greater than minus p.turn_recognition_angle: it left the intersection without turning right.", "params": ["p.heading_since_step_carla_scene_graph", "p.turn_recognition_angle"], "narrowings": [{"span": "d1", "why": "'has been designed to provide' is read through the lane's presence as mapped: a right turn lane on the highway evidences the design.", "kind": "observable_reading", "category": "status"}, {"span": "d4", "why": "'Be driven' is read through the vehicle's controlled motion in the lane, whoever or whatever controls it.", "kind": "observable_reading", "category": "agency"}, {"span": "d5", "why": "'only for the purpose of making a right turn' is read through the conduct the purpose explains: a vehicle in the lane leaves it either by turning right (into the intersection the lane enters, with a right turn, or off to the right before it); leaving it back into the neighbouring lane on its left short of the intersection, or leaving the intersection it entered from the lane without a right turn, is the lane used for another purpose.", "kind": "observable_reading", "category": "purpose"}], "scenarios": [{"name": "forbid", "expected": "violated", "narrative": "A car enters the single right turn lane to pass a queue of through traffic, then moves back into the through lane on its left before reaching the intersection."}, {"name": "permit", "expected": "compliant", "narrative": "A car drives in the single right turn lane, enters the intersection the lane runs into and turns a quarter turn to the right before leaving it."}, {"name": "idle", "expected": "not_applicable", "narrative": "A car approaches an intersection on a highway whose approach has no right turn lane."}, {"name": "blind", "expected": "unknown", "narrative": "A car enters the intersection from the single right turn lane and leaves it; the source declares kin.yaw_rate absent, so whether it turned right is not observed.", "masked": ["kin.yaw_rate"]}, {"name": "branch_1", "expected": "not_applicable", "narrative": "A car changes back out of the rightmost of two adjacent right turn lanes: the highway provides a dual, not a single, right turn lane."}, {"name": "branch_2", "expected": "violated", "narrative": "A car in the single right turn lane drives straight through the intersection and leaves it with its heading unchanged."}], "literals": [], "param_proposals": [{"name": "p.turn_recognition_angle", "unit": "deg", "value": 45, "convention": "Turn recognition: the heading change through an intersection beyond which a passage counts as a turn rather than a straight crossing; half the right angle of a turn at a right-angled junction, leaving room for skewed junctions and lane offsets.", "source": "Intersection geometry conventions (AASHTO Green Book turning paths) and manoeuvre classification in trajectory datasets"}], "gaps": []}
{"node_id": "NRS_484B_223_4b", "law_refs": ["NRS-484B-223-4b"], "subject": {"binder": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}, "segmentation": [{"id": "e1", "text": "If a highway has been designed to provide", "role": "condition"}, {"id": "e2", "text": "a single right lane to be used only for turning", "role": "condition"}, {"id": "e3", "text": "a vehicle must", "role": "subject"}, {"id": "e4", "text": "While being driven in the right turn lane", "role": "condition"}, {"id": "e5", "text": "not travel through an intersection", "role": "obligation"}], "elements": [{"span": "e1", "atoms": ["st.highway", "st.on_way"], "derived": [], "justification": "st.highway is 'the entire public way between its boundary lines', denoting DEF-NRS-484A-095 ('the entire width between the boundary lines of every way dedicated to a public authority ...'); st.on_way ('the public way (a highway region) a structure region lies on — a lane, roadway, ...') ties the turn lane to that highway. 'has been designed to provide' is the lane's presence on the map (status reading below)."}, {"span": "e2", "atoms": ["st.turn_lane", "st.lane", "st.lane_adjacency"], "derived": [], "justification": "st.turn_lane is 'a lane designated only for turning; side ∈ {left, right}', with side right: 'a ... right lane to be used only for turning'. 'single' is read as no neighbouring lane being a right turn lane too: st.lane_adjacency gives the 'left / right neighbouring lane of the same direction' (its exclusion 'Not a stand-in for: the marking between two lanes' is respected: lanes, not markings, are compared), so a pair of adjacent right turn lanes is not a single one."}, {"span": "e3", "atoms": ["ru.aggregate=DEF-NRS-484A-320::vehicle"], "derived": [], "justification": "'a vehicle' is the admitted aggregate DEF-NRS-484A-320::vehicle, claimed as one atom; 'must' introduces the duty the obligation span states."}, {"span": "e4", "atoms": ["st.turn_lane", "rel.occupies"], "derived": [], "justification": "'the right turn lane' is the lane L the condition singles out (st.turn_lane, side right); 'being driven in' it is x's footprint overlapping it (rel.occupies), read at the observation at which x's footprint begins to overlap the intersection: the moment the travel through begins."}, {"span": "e5", "atoms": ["st.intersection", "st.lane_enters", "rel.occupies", "kin.yaw_rate"], "derived": ["drv.motion.heading_change_since_entry"], "justification": "'an intersection' is the st.intersection ('the region where two roadways meet, bounded by the prolongation of their edges', DEF-NRS-484A-105) the turn lane runs into (st.lane_enters, 'the intersection region a directed approach carrier runs into at its entrance end'); a turn lane reaches no other. 'travel through' it is entering it from the lane and leaving it (rel.occupies rising, then falling) without the heading change of a right turn: drv.motion.heading_change_since_entry (from kin.yaw_rate, left positive; 'Not a stand-in for: road curvature' is respected, the vehicle's own heading change over the passage is read) not reaching minus the turn recognition angle by the exit."}], "operationalizations": [], "assumptions": [], "intentions": [], "compositions": [], "residues": [], "binders": [{"name": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}], "applicability": "x is a vehicle (ru.aggregate DEF-NRS-484A-320::vehicle) and x occupies (rel.occupies) at the observation, or occupied at an earlier observation, a single right turn lane L: an st.turn_lane region of side right lying on (st.on_way) an st.highway region, with no lane adjacent to it (st.lane_adjacency) that is also an st.turn_lane of side right.", "obligation": "Re-binding L with the same selection and I as the st.intersection region L enters (st.lane_enters): at the observation it is not the case that x stops here occupying I (rel.occupies of x and I false here and true at the previous observation), having begun to overlap I at an observation at which it occupied L, with its heading change since that entry (drv.motion.heading_change_since_entry(x, I), step p.heading_since_step_carla_scene_graph) greater than minus p.turn_recognition_angle.", "params": ["p.heading_since_step_carla_scene_graph", "p.turn_recognition_angle"], "narrowings": [{"span": "e1", "why": "'has been designed to provide' is read through the lane's presence as mapped: a right turn lane on the highway evidences the design.", "kind": "observable_reading", "category": "status"}, {"span": "e4", "why": "'being driven' is read through the vehicle's controlled motion in the lane, whoever or whatever controls it.", "kind": "observable_reading", "category": "agency"}, {"span": "e5", "why": "'travel through an intersection' is read as entering the intersection from the turn lane and leaving it without turning right: a straight passage and a left turn alike; a passage still under way when the recording ends is not decided.", "kind": "reading"}], "scenarios": [{"name": "forbid", "expected": "violated", "narrative": "A car in the single right turn lane enters the intersection the lane runs into and drives straight across it, leaving with its heading unchanged."}, {"name": "permit", "expected": "compliant", "narrative": "A car in the single right turn lane enters the intersection and turns a quarter turn to the right before leaving it."}, {"name": "idle", "expected": "not_applicable", "narrative": "A car drives straight through an intersection from a through lane on a highway whose approach has no right turn lane."}, {"name": "blind", "expected": "unknown", "narrative": "A car enters the intersection from the single right turn lane and leaves it; the source declares kin.yaw_rate absent, so whether it turned right is not observed.", "masked": ["kin.yaw_rate"]}, {"name": "branch_1", "expected": "compliant", "narrative": "A car in the single right turn lane moves back into the through lane on its left before the intersection and later crosses the intersection from the through lane: it never entered the intersection from the turn lane."}], "literals": [], "param_proposals": [{"name": "p.turn_recognition_angle", "unit": "deg", "value": 45, "convention": "Turn recognition: the heading change through an intersection beyond which a passage counts as a turn rather than a straight crossing; half the right angle of a turn at a right-angled junction, leaving room for skewed junctions and lane offsets.", "source": "Intersection geometry conventions (AASHTO Green Book turning paths) and manoeuvre classification in trajectory datasets"}], "gaps": []}
{"node_id": "NRS_484B_227_1_o1", "law_refs": ["NRS-484B-227-1"], "subject": {"binder": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}, "segmentation": [{"id": "a1", "text": "Every vehicle driven", "role": "subject"}, {"id": "a2", "text": "upon a divided highway", "role": "trigger"}, {"id": "a3", "text": "must be driven only upon the right-hand roadway", "role": "obligation"}, {"id": "a4", "text": "and", "role": "boilerplate"}, {"id": "a5", "text": "must not be driven over, across or within any dividing space, barrier or section", "role": "sibling"}, {"id": "a6", "text": "or make any left turn, semicircular turn or U-turn", "role": "sibling"}, {"id": "a7", "text": "except through an opening in the barrier or dividing section or space", "role": "sibling"}, {"id": "a8", "text": "or at a crossover or intersection", "role": "sibling"}, {"id": "a9", "text": "established by a public authority", "role": "sibling"}], "elements": [{"span": "a1", "atoms": ["ru.aggregate=DEF-NRS-484A-320::vehicle"], "derived": [], "justification": "'vehicle' is the admitted aggregate DEF-NRS-484A-320::vehicle, claimed as one atom; 'driven' is read through the vehicle's controlled motion (agency reading below)."}, {"span": "a2", "atoms": ["st.highway", "st.on_way", "st.median_or_divider", "st.roadway", "rel.occupies"], "derived": [], "justification": "A divided highway is 'a highway divided into two or more roadways by means of a physical barrier or dividing section' (DEF-NRS-484A-070): an st.highway ('the entire public way between its boundary lines') on which (st.on_way) an st.median_or_divider lies ('physical barrier or dividing section between roadways'), its parts being st.roadway regions ('separate roadways of a divided highway are separate'). 'upon' is x's footprint overlapping (rel.occupies) a roadway or dividing section lying on that highway; st.highway's exclusion 'Not a stand-in for: the roadway' is respected: the roadway is read as the part of the way it is."}, {"